"""Read-only complete-local-tap integrity/equivalence check, no GPU calls."""
from pathlib import Path
import json,hashlib,sys
import numpy as np
NAMES={'film-sensitivity.cpu.f64':(243,'<f8'),'tc-b-matrix.cpu.f64':(9,'<f8'),'tc-b-matrix.uploaded.f32':(9,'<f4'),'tc-b-matrix.device.f32':(9,'<f4'),'tc-lut.cpu.f64':(110592,'<f8'),'tc-lut.uploaded.f32':(110592,'<f4'),'tc-lut.device.f32':(110592,'<f4'),'exposure-scale.cpu.f64':(3,'<f8'),'exposure-offset.cpu.f64':(3,'<f8'),'exposure-scale.uploaded.f32':(3,'<f4'),'exposure-offset.uploaded.f32':(3,'<f4'),'00-input.device.f32':(1683,'<f4'),'01-tc.device.f32':(1122,'<f4'),'02-brightness.device.f32':(561,'<f4'),'03-upsample.device.f32':(1683,'<f4'),'04-exposure.device.f32':(1683,'<f4')}
def need(ok,m):
 if not ok:raise ValueError(m)
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def validate(root,role):
 repo=Path(__file__).resolve().parents[3];identity=json.loads((root/'execution-before.json').read_text());r=json.loads((root/'run.json').read_text());need(identity['role']==role and r['success'] and not r['cleanupErrors'],'Run/role/cleanup failed');need(sha(root/'execution-before.json')==r['receiptSha256'],'Run receipt mismatch');need(r['gpuApiCounts']=={'engineCreate':1,'open':1,'wholeRender':1,'streamRender':0,'btProbe':0},'One gray call scope violated');expected=json.loads((Path(__file__).parent/'fixtures/fixtures.json').read_text())['fixtures'][0];need(identity['inputIdentity']==expected and sha(root/'input.npy')==expected['fileSha256'],'Fixed input mismatch');need(identity['resolved']==json.loads((Path(__file__).parent/'resolved-portraA.json').read_text())==r['actualResolved'],'Resolved mismatch');need(identity['resources']==json.loads((Path(__file__).parent/'expected-resources.json').read_text()),'Resources mismatch');need(r['outputHash']==sha(root/'whole-observed.rgba16'),'Output changed');records={x['file']:x for x in r['observations']};need(len(records)==len(r['observations'])==17,'Missing/duplicate observation');data={}
 for name,(n,dtype) in NAMES.items():
  p=root/'taps'/name;meta=records['taps/'+name];need(p.stat().st_size==n*np.dtype(dtype).itemsize and sha(p)==meta['sha256'],'Observation bytes mismatch '+name);v=np.fromfile(p,dtype=dtype);need(np.isfinite(v).all(),'Nonfinite '+name);data[name]=v
 need(np.array_equal(data['00-input.device.f32'].view('<u4'),np.load(root/'input.npy').reshape(-1).view('<u4')),'Device input changed')
 bytechecks=[]
 for name in ['tc-b-matrix','tc-lut']:
  bytechecks.append({'constant':name,'cpuNarrowVsUploadChangedBits':int((data[name+'.cpu.f64'].astype('<f4').view('<u4')!=data[name+'.uploaded.f32'].view('<u4')).sum()),'uploadVsDeviceChangedBits':int((data[name+'.uploaded.f32'].view('<u4')!=data[name+'.device.f32'].view('<u4')).sum())})
 exposureSame=bool(np.array_equal(data['03-upsample.device.f32'].view('<u4'),data['04-exposure.device.f32'].view('<u4')));scaleExpected=bool(np.array_equal(data['exposure-scale.uploaded.f32'],[1,1,1]) and np.array_equal(data['exposure-offset.uploaded.f32'],[0,0,0]));modefile=root/'taps/selected-math-mode.jsonl';need(sha(modefile)==records['taps/selected-math-mode.jsonl']['sha256'],'Mode file changed');modes=[json.loads(x) for x in modefile.read_text().splitlines()];need([x['kernel'] for x in modes]==['spk_tc_b','spk_lut2d_cubic','spk_affine3'] and all(x['fused_fma_runtime'] in [0,1] and x['specialization_bool'] in [0,1] and x['specialization_id']==0 for x in modes),'Mode record incomplete')
 sealed=repo/'docs/research/color-engine-20261029'/('company-diagnostic-20261102/company-package' if role=='company' else 'home-round11/diagnostic-home-v2')/'gray-boundaries/whole.rgba16';need(sha(root/'whole-observed.rgba16')==sha(sealed),'Passive final changed vs corresponding sealed side')
 return r,identity,{'version':'CompleteLocalGraySubstageValidationV1','role':role,'finiteArtifacts':len(NAMES),'fixedGrayInputExact':True,'constantByteObservations':bytechecks,'narrowedStagingDeviceBytesExact':all(x['cpuNarrowVsUploadChangedBits']==x['uploadVsDeviceChangedBits']==0 for x in bytechecks),'EV0ActualConstantsExpected':scaleExpected,'EV0ExposureBitIdentityObserved':exposureSame,'numericalObservationsAreNotValidatorAssumptions':True,'sealedSideFinalExact':True,'GPUCallsForValidation':0,'fullLocalCaptureValidated':True}
if __name__=='__main__':
 import argparse
 p=argparse.ArgumentParser();p.add_argument('run',type=Path);p.add_argument('--role',required=True,choices=['home','company']);a=p.parse_args();_,_,result=validate(a.run,a.role);print(json.dumps(result,indent=2))
